import{_ as r,C as a,c as i,o as n,a3 as t,G as o}from"./chunks/framework.Dokpd4od.js";const x=JSON.parse('{"title":"Pricing and taxes","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/point-of-sale/products-pricing/pricing-and-taxes.md","filePath":"master/sales/point-of-sale/products-pricing/pricing-and-taxes.md","lastUpdated":1792041590000}'),l={name:"master/sales/point-of-sale/products-pricing/pricing-and-taxes.md"};function c(d,e,g,p,h,u){const s=a("ImagePopup");return n(),i("div",null,[e[0]||(e[0]=t('<h1 id="pricing-and-taxes" tabindex="-1">Pricing and taxes <a class="header-anchor" href="#pricing-and-taxes" aria-label="Permalink to &quot;Pricing and taxes&quot;">​</a></h1><p>The price a customer pays at the till depends on the product price, the taxes, any price list and any discount. You control each of these. This page shows where, and how they add up on an order.</p><blockquote><p><strong>In simple words:</strong> Pick whether shelf prices include tax, choose the taxes, then decide who may give a discount.</p></blockquote><h2 id="taxes" tabindex="-1">Taxes <a class="header-anchor" href="#taxes" aria-label="Permalink to &quot;Taxes&quot;">​</a></h2><p>Go to <code>Point of Sale → Configurations → Taxes</code>.</p>',5)),o(s,{src:"/images1/pos/pos_taxes_list.png",alt:"Point of Sale → Configurations → Taxes list with the 15 % Sale tax of My Company"}),e[1]||(e[1]=t('<p>The list shows <strong>Name</strong>, <strong>Company</strong>, <strong>Tax Group</strong>, <strong>Tax Type</strong>, <strong>Invoice Label</strong> and <strong>Status</strong>. Use the tabs for <strong>Sale</strong> and <strong>Purchase</strong>. The filters cover <strong>Tax Scope</strong>, <strong>Goods</strong> and <strong>Active</strong> or inactive taxes.</p><p>Click <strong>New Tax</strong> to add one. The form asks for:</p><ul><li><strong><em>Name:</em></strong> Required. For example <strong>15 %</strong>.</li><li><strong><em>Tax Type:</em></strong> Required. <strong>Sale</strong> or <strong>Purchase</strong>.</li><li><strong><em>Tax Computation:</em></strong> Required. How the amount is worked out.</li><li><strong><em>Tax Scope:</em></strong> Goods or services.</li><li><strong><em>Amount:</em></strong> Required. The rate in percent.</li><li><strong><em>Advanced Options:</em></strong> <strong>Invoice label</strong>, <strong>Tax Group*</strong>, <strong>Country</strong> and <strong>Included in Price</strong>.</li></ul><p>The Finance module owns taxes. Read <a href="./../../../finance/taxes/taxes.html">Taxes</a> for every field and the repartition lines.</p><h3 id="attach-taxes-to-a-product" tabindex="-1">Attach taxes to a product <a class="header-anchor" href="#attach-taxes-to-a-product" aria-label="Permalink to &quot;Attach taxes to a product&quot;">​</a></h3><p>Open the product and choose <strong>Product taxes</strong>. Every sale of that product at the till uses them. See <a href="./products.html">Products</a>.</p><h2 id="tax-excluded-or-tax-included" tabindex="-1">Tax excluded or tax included <a class="header-anchor" href="#tax-excluded-or-tax-included" aria-label="Permalink to &quot;Tax excluded or tax included&quot;">​</a></h2><p>Each register decides how it shows prices.</p><ol><li>Go to <code>Point of Sale → Configurations → Point of Sale</code> and open a register.</li><li>Open the <strong>Pricing</strong> tab.</li><li>Set <strong>Product Prices*</strong> to <strong>Tax Excluded</strong> or <strong>Tax Included</strong>.</li></ol>',9)),o(s,{src:"/images1/pos/register_pricing_tab.png",alt:"Register Pricing tab with Product Prices set to Tax Excluded and line discounts switched on"}),e[2]||(e[2]=t('<ul><li><strong>Tax Excluded:</strong> The grid shows the price before tax. The tax is added at the total.</li><li><strong>Tax Included:</strong> The grid shows the price the customer pays.</li></ul><h3 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h3><p>A product has a price of 1,000 and a 15 % tax. With <strong>Tax Excluded</strong>, the line shows 1,000, the tax is 150 and the total is 1,150. With <strong>Tax Included</strong>, the line shows 1,150.</p><h2 id="price-lists" tabindex="-1">Price lists <a class="header-anchor" href="#price-lists" aria-label="Permalink to &quot;Price lists&quot;">​</a></h2><p>A price list gives a product a different price for a group of customers or a time. It is optional.</p><ol><li>Go to <code>Point of Sale → Settings → Products</code>.</li><li>Switch on <strong>Price Lists</strong> (&quot;Allow products to be sold at prices set by a price list&quot;).</li><li>Click <strong>Save changes</strong>.</li></ol><p>Now <code>Point of Sale → Products → Price Lists</code> appears. Each price list has a <strong>Price List Name</strong>, <strong>Currency</strong>, <strong>Company</strong>, an <strong>Active</strong> switch and price rules. The first matching rule decides the price, and more specific rules win.</p><p>Then open the register, tab <strong>Pricing</strong>:</p><ul><li><strong><em>Flexible Pricelists:</em></strong> Lets cashiers switch price lists at the till.</li><li><strong><em>Default Pricelist:</em></strong> The list applied to every order on this register.</li><li><strong><em>Available Pricelists:</em></strong> The lists cashiers may choose. It shows when flexible pricelists are on.</li></ul>',9)),o(s,{src:"/images1/pos/register_pricing_pricelists.png",alt:"Register Pricing tab with Flexible Pricelists on and Default Pricelist selected"}),e[3]||(e[3]=t('<p>Price rules work as in Sales. See <a href="./../../sales/products-prices/price-lists.html">Price lists</a>.</p><h2 id="discounts" tabindex="-1">Discounts <a class="header-anchor" href="#discounts" aria-label="Permalink to &quot;Discounts&quot;">​</a></h2><p>Two switches on the register <strong>Pricing</strong> tab control discounts.</p><ul><li><strong><em>Line Discounts:</em></strong> Cashiers can set a discount on one line. Use the <strong>%</strong> mode on the numpad.</li><li><strong><em>Global Discounts:</em></strong> A button gives a discount on the whole order. After you switch it on, set the <strong>Discount Product</strong> and <strong>Discount %</strong>, the default percent the button offers.</li><li><strong><em>Price Control:</em></strong> Only managers may change a price.</li></ul><p>The discount shows on the order in the <strong>Discount (%)</strong> column. See <a href="./../../sales/products-prices/discounts-margins.html">Discounts and margins</a>.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>Global Discounts</strong> is locked while a session is open. Close the session first, then change it.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../../../finance/taxes/taxes.html">Taxes in Finance</a></li><li><a href="./../../../finance/taxes/fiscal-positions.html">Fiscal positions</a></li><li><a href="./../../sales/products-prices/price-lists.html">Price lists in Sales</a></li><li><a href="./../get-started/set-up-a-register.html">Set up a register</a></li></ul>',8))])}const f=r(l,[["render",c]]);export{x as __pageData,f as default};
